import AVFoundation
import AppKit
let args=CommandLine.arguments
let url=URL(fileURLWithPath:args[1]); let out=args[2]; let step=Double(args[3])!
let a=AVURLAsset(url:url)
let g=AVAssetImageGenerator(asset:a); g.appliesPreferredTrackTransform=true; g.maximumSize=CGSize(width:1280,height:1280)
g.requestedTimeToleranceBefore = .zero; g.requestedTimeToleranceAfter = .zero
let dur=CMTimeGetSeconds(a.duration); print(args[1],"dur",dur, "audio tracks", a.tracks(withMediaType:.audio).count)
var t=0.0; var i=0
while t<dur { 
 if let c=try? g.copyCGImage(at:CMTime(seconds:t,preferredTimescale:600),actualTime:nil){
  let r=NSBitmapImageRep(cgImage:c); let d=r.representation(using:.jpeg,properties:[.compressionFactor:0.6])!
  try! d.write(to:URL(fileURLWithPath:String(format:"%@_%04d.jpg",out,i))) }
 i+=1; t+=step }
print("frames",i)
EOF
cat > scripts/ocr.swift <<'EOF'
import Vision
import AppKit
for p in CommandLine.arguments.dropFirst() {
 guard let img=NSImage(contentsOfFile:p), let c=img.cgImage(forProposedRect:nil,context:nil,hints:nil) else {continue}
 let q=VNRecognizeTextRequest(); q.recognitionLevel = .accurate
 try? VNImageRequestHandler(cgImage:c,options:[:]).perform([q])
 let t=(q.results ?? []).compactMap{$0.topCandidates(1).first?.string}.joined(separator:" | ")
 print("\((p as NSString).lastPathComponent): \(t)")
}
EOF
